package dev.zomboid.hordes;import java.util.*;public class ZoneReserve{public static int limit;static Map<Object,Object>LEVELS=new HashMap<>();public static class State{Map<Object,Object>active=new HashMap<>();}public static Object state(Object level){return LEVELS.computeIfAbsent(level,k->new State());}public static boolean zombie(Object e){return e instanceof BudgetChecks49.Zombie;}public static boolean protectedNow(Object s,Object e,Object l){return ((BudgetChecks49.Zombie)e).combat;}public static void queue(Object s,Object e){((State)s).active.remove(((BudgetChecks49.Zombie)e).getUUID());}}
